 const nameKey=value=>String(value||'').trim().toLowerCase();
 const conflicts=(module,from,to)=>from!==to&&Object.values(statuses).some(status=>
  ['temperatureReadings','temperatureCorrections'].some(key=>{
   const values=status&&status[key]&&status[key][module];
   return values&&Object.prototype.hasOwnProperty.call(values,from)&&Object.prototype.hasOwnProperty.call(values,to)
  }));
 const reservedIds=new Set();
 TEMP_MODULES.forEach(module=>definitions[module].forEach(category=>(category.items||[]).forEach(item=>reservedIds.add(String(item.id)))));
 Object.values(statuses).forEach(status=>['temperatureReadings','temperatureCorrections'].forEach(key=>{
  TEMP_MODULES.forEach(module=>Object.keys(status&&status[key]&&status[key][module]||{}).forEach(id=>reservedIds.add(id)))
 }));
 let nextId=S.n;
 const freshId=()=>{let id;do{id='shared-temp-item-'+nextId++}while(reservedIds.has(id));reservedIds.add(id);return id};
 TEMP_MODULES.forEach(module=>{
  mappings[module]=new Map();
  definitions[module].forEach(category=>{
   let target=shared.find(entry=>nameKey(entry.name)===nameKey(category.name));
   if(!target){target=Object.assign({},category,{items:[]});shared.push(target)}
   (category.items||[]).forEach(item=>{
    const source=String(item.id),candidate=target.items.find(entry=>nameKey(entry.item.text)===nameKey(item.text)&&!entry.modules.has(module)&&!conflicts(module,source,String(entry.item.id)));
    let dest;
    if(candidate){dest=candidate;dest.modules.add(module)}
    else{
     const id=usedIds.has(source)?freshId():item.id;
     dest={item:Object.assign({},item,{id}),modules:new Set([module])};
     target.items.push(dest);usedIds.add(String(id))
    }
    if(mappings[module].has(source)&&mappings[module].get(source)!==String(dest.item.id))throw new Error('Duplicate temperature item IDs in '+module+'.');
    mappings[module].set(source,String(dest.item.id))
   })
  })
 });
