   renameError=h('div',{class:'err'}),
   itemRows=category.items.map(item=>{
    const itemInput=h('input',{type:'text',value:item.text,'aria-label':kind+' item'}),limits=temperatureFields(item),
     itemError=h('div',{class:'err'});
    return h('div',{class:'frm walk-item-row'},
     h('div',{class:limits?'walk-config-row':'walk-inline-row'},h('div',{class:'walk-inline-field'},field('Item',itemInput)),
      limits?field('Minimum (°F)',limits.min):null,limits?field('Maximum (°F)',limits.max):null,h('div',{class:'walk-inline-actions'},
      h('button',{class:'btn alt',text:'Save',title:'Save item',onclick:()=>{
       const text=itemInput.value.trim();
       if(!text){itemError.textContent='Enter an item name.';return}
       if(category.items.some(other=>other!==item&&other.text.trim().toLowerCase()===text.toLowerCase())){itemError.textContent='An item with that name already exists in this category.';return}
       const values=readTemperatureFields(limits,itemError);if(!values)return;
       const previous=Object.assign({},item);Object.assign(item,values,{text});
       if(!save()){Object.keys(item).forEach(key=>delete item[key]);Object.assign(item,previous);t('Unable to save the item. Browser storage may be full.');return}
       redraw();t('Item updated.')
      }}),
      h('button',{class:'btn alt',text:'Delete',title:'Delete item',onclick:()=>{
       if(!window.confirm('Delete the '+kind+' item "'+item.text+'"?'+(temperatureGroup?' It will be removed from all three temperature logs.':'')))return;
       const index=category.items.indexOf(item);category.items.splice(index,1);
       if(!save()){category.items.splice(index,0,item);t('Unable to delete the checklist item.');return}
       redraw();t('Item deleted.')
      }}))),itemError)
   }),
   newItem=h('input',{type:'text',placeholder:'New item name'}),newLimits=temperatureFields({}),
