const RESET_CODE_HOURS=24,RESET_CODE_MAX_TRIES=5;
async function issueResetCode(u,result,err){
 const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',code=Array.from(crypto.getRandomValues(new Uint8Array(8)),b=>alphabet[b%alphabet.length]).join('');
 u.resetCode={hash:await hashPassword(code),exp:Date.now()+RESET_CODE_HOURS*3600000,tries:0};
 if(!save()){delete u.resetCode;err.textContent='Unable to save the reset code.';return}
 result.textContent='Reset code: '+code+' — give it to '+u.name+' securely. It works once and expires in '+RESET_CODE_HOURS+' hours.';result.classList.remove('hidden');err.textContent=''
}
async function submitPasswordReset(){
 const email=$('rsEmail').value.trim().toLowerCase(),code=$('rsCode').value.trim().toUpperCase(),pw=$('rsPw').value,pw2=$('rsPw2').value,err=$('rsErr'),generic='That email and reset code do not match, or the code has expired.';
 err.textContent='';
 if(!email||!code||!pw||!pw2){err.textContent='Please complete every field.';return}
 if(pw.length<8){err.textContent='New password must be at least 8 characters.';return}
 if(pw!==pw2){err.textContent='Passwords do not match.';return}
 try{
  const account=items('users').find(u=>typeof u.email==='string'&&u.email.trim().toLowerCase()===email),rc=account&&account.resetCode;
  if(!account||!account.on||!rc||Date.now()>rc.exp||rc.tries>=RESET_CODE_MAX_TRIES){err.textContent=generic;return}
  if(await hashPassword(code,rc.hash.split(':')[0])!==rc.hash){rc.tries++;save();err.textContent=generic;return}
  account.passwordHash=await hashPassword(pw);delete account.resetCode;save();
  ['rsEmail','rsCode','rsPw','rsPw2'].forEach(id=>$(id).value='');
  $('u').value=email;$('p').value='';show('login');t('Password updated. Please sign in.')
 }catch(e){console.error('Unable to reset password:',e);err.textContent=e.message||'Unable to reset password. Please try again.'}
}
