async function go(){const email=$('u').value.trim().toLowerCase(),password=$('p').value,err=$('err');
 if(!email||!password){err.textContent='Please enter your email address and password.';return}
 err.textContent='';
 try{
  if(!items('users').some(u=>u.passwordHash)){
   const account=items('users').find(u=>typeof u.email==='string'&&u.email.trim().toLowerCase()===email);
   if(!account||!account.on){err.textContent='Email or password is incorrect.';return}
   CURRENT_USER_ID=account.id;rememberSession();   setHomeUser(account);
   show('home');
   return;
  }
  const account=items('users').find(u=>typeof u.email==='string'&&u.email.trim().toLowerCase()===email);
  const salt=account&&account.passwordHash&&account.passwordHash.split(':')[0];
  if(!account||!account.on||!salt||!/^[a-f0-9]{32}$/i.test(salt)||await hashPassword(password,salt)!==account.passwordHash){err.textContent='Email or password is incorrect.';return}
  account.last=new Date().toLocaleDateString();save();CURRENT_USER_ID=account.id;rememberSession();setHomeUser(account);show('home');
 }catch(e){console.error('Unable to verify login credentials:',e);err.textContent=e.message||'Unable to sign in securely. Please try again.'}
}
