let INSIGHTS_FILTER={store:'all',range:'30',from:'',to:''};
function insightsKey(date){return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0')}
function insightsParse(key){const [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d)}
function insightsDays(filter){
 let start,end=new Date();
 if(filter.range==='custom'){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(filter.from)||!/^\d{4}-\d{2}-\d{2}$/.test(filter.to))return null;
  start=insightsParse(filter.from);end=insightsParse(filter.to);
  if(end<start||(end-start)/864e5>365)return null
 }else{start=new Date();start.setDate(start.getDate()-(Number(filter.range)-1))}
 const days=[];
 for(let d=new Date(start.getFullYear(),start.getMonth(),start.getDate());d<=end;d.setDate(d.getDate()+1))days.push(insightsKey(d));
 return days
}
function insightsDuration(ms){
 const hours=ms/36e5;
 return hours<1?Math.max(1,Math.round(ms/6e4))+' min':hours<48?(Math.round(hours*10)/10)+' hrs':(Math.round(hours/24*10)/10)+' days'
}
