const DEMO_EMAIL='admin@shifthero.demo';
function populateDemoData(passwordHash){
   const users=S.d.users=Array.isArray(S.d.users)?S.d.users:[];
   if(!users.some(account=>String(account.email).toLowerCase()===DEMO_EMAIL)){
    const now=new Date(),dayKey=n=>insightsKey(new Date(now.getFullYear(),now.getMonth(),now.getDate()-n)),
     dayTime=(n,hour)=>new Date(now.getFullYear(),now.getMonth(),now.getDate()-n,hour).getTime(),
     hasLocation=id=>S.locations.some(location=>location.id===id),
     admin={id:nid(),first:'Demo',last:'Administrator',name:'Demo Administrator',email:DEMO_EMAIL,passwordHash,phone:'',role:'System Administrator',level:'Corporate',locationId:hasLocation('loc-home-office')?'loc-home-office':undefined,store:'Home Office',on:true,last:'Never',perms:defaultRolePermissions('System Administrator')},
     store={id:'loc-demo-store',name:'#10001 - Demo Restaurant, Anytown',type:'Store',parentId:hasLocation('loc-southeast')?'loc-southeast':null};
    users.push(admin);
    if(!hasLocation(store.id))S.locations.push(store);
    S.dailyLocationSelection=S.dailyLocationSelection||{};
    S.dailyLocationSelection[admin.id]=store.id;
    const make=(prefix,name,texts)=>({id:prefix+'-category-'+nid(),name,items:texts.map(text=>({id:prefix+'-item-'+nid(),text}))});
    if(!S.walkthroughItems.categories.length){
     S.walkthroughItems.categories=[
      make('walk','Labels',['All prep items are labeled and dated','Expired product has been removed']),
      make('walk','Dining Room',['Tables and chairs are clean','Floors are swept and mopped']),
      make('walk','Tea Station',['Tea is freshly brewed','Tea station is stocked and clean']),
      make('walk','Bathrooms',['Bathrooms are clean and stocked','Trash has been emptied'])
     ];
     const levels=['critical','high','high','medium','medium','medium','high','medium'];
     let priorityIndex=0;
     S.walkthroughItems.categories.forEach(category=>category.items.forEach(item=>{
      item.priority=levels[priorityIndex++];item.defaultDueDays=PRIORITY_DUE_DEFAULTS[item.priority];
      S.walkthroughPriorities[item.id]=item.priority
     }))
    }
    ['check_opening','check_midday','check_closing'].forEach((module,index)=>{
     if(!S.checklistDefinitions[module].length)S.checklistDefinitions[module]=[make('check',['Opening','Mid-Day','Closing'][index]+' Tasks',[['Unlock and turn on equipment','Check the cash drawer','Stock the line'],['Restock the line','Wipe down stations','Check the dining room'],['Clean the equipment','Take out the trash','Lock up and set the alarm']][index])]
    });
    if(temperatureSharedReady&&!S.temperatureDefinitions.shared.length)S.temperatureDefinitions.shared=[make('temp','Refrigeration',['Walk-In Cooler','Sandwich Prep Cooler','Freezer']),make('temp','Hot Holding',['Hot Hold Soup'])];
    if(!S.actionItems.length&&!Object.keys(S.dailyStatus||{}).length){
     S.dailyStatus=S.dailyStatus||{};
     const walkItems=S.walkthroughItems.categories.flatMap(category=>category.items||[]),
      missRate=[.55,.35,.4,.3,.25,.45,.2,.15];
     for(let n=20;n>=0;n--){
      const status=S.dailyStatus[dayKey(n)+'|'+store.id]={dailySubmissions:{},submittedAt:{},walkthroughItems:{},checklistItems:{},temperatureReadings:{}},
       done=(module,hour)=>{status.dailySubmissions[module]=true;status.submittedAt[module]=dayTime(n,hour)};
      [['walk_morning',8,0],['walk_evening',20,1]].forEach(([module,hour,evening])=>{
       if(n===0&&evening||n%9===4&&evening)return;
       const checks=status.walkthroughItems[module]={};
       walkItems.forEach((item,index)=>{
        const roll=((n*37+index*53+evening*29+17)%100)/100;
        if(roll>=(missRate[index%missRate.length]||.2)*(.35+n/20*.8)*(evening?.7:1))checks[item.id]=true
       });
       done(module,hour);
       generateWalkthroughActions(module,status,dayKey(n),store).forEach((action,index)=>{
        action.created=dayTime(n,hour);
        if(n>=5||n>=2&&index%2===0){action.status='Done';action.completed=action.created+(3+(index*7+n)%27)*36e5}
        else if(n>=1||index%2===0)action.status='In Progress'
       })
      });
      [['check_opening',7],['check_midday',12],['check_closing',22]].forEach(([module,hour],index)=>{
       if(index&&n===0)return;
       const checks=status.checklistItems[module]={};
       (S.checklistDefinitions[module]||[]).forEach(category=>(category.items||[]).forEach((item,position)=>{if((n+position+index)%7!==3)checks[item.id]=true}));
       done(module,hour)
      });
      [['temp_morning',8],['temp_midday',13],['temp_evening',19]].forEach(([module,hour],index)=>{
       if(index&&n===0)return;
       const readings=status.temperatureReadings[module]={};
       temperatureItemsFor(module).forEach(category=>(category.items||[]).forEach((item,position)=>{
        const wobble=(n*3+position*5+index*2)%5;
        readings[item.id]=String(/freezer/i.test(item.text)?-4+wobble:/hot/i.test(item.text)?(n%8===3?130:140+wobble*2):36+wobble-(n%10===6?-5:0))
       }));
       done(module,hour)
      })
     }
    }
    if(!S.mvrVisits.length){
     [[50,{'Food Safety':3,'Cleanliness':2,'Operational Standards':4,'Guest Experience':4,'Team Leadership':3,'Restaurant Readiness':3},{'Cleanliness':'Dining room and restrooms need more frequent checks during peak.'},{'Cleanliness':'Tables sticky during lunch rush.'}],
      [25,{'Food Safety':4,'Cleanliness':3,'Operational Standards':4,'Guest Experience':4,'Team Leadership':4,'Restaurant Readiness':4},{'Team Leadership':'Good coaching on the line.'},{}],
      [6,{'Food Safety':2,'Cleanliness':4,'Operational Standards':4,'Guest Experience':5,'Team Leadership':4,'Restaurant Readiness':5},{'Food Safety':'Labels and dates were missed on several prep items.'},{'Food Safety':'Label compliance gaps in the walk-in cooler.'}]
     ].forEach(([n,ratings,comments,findings])=>{
      const visit={id:'mvr-'+nid(),created:dayTime(n,10),date:dayKey(n),locationId:store.id,reviewer:admin.name,reviewerRole:admin.role,reviewerId:admin.id,ratings,comments,findings,status:'Complete',score:mvrScore(ratings)};
      S.mvrVisits.push(visit);
      generateMvrActions(visit).forEach(action=>{
       action.created=visit.created;
       if(n>=25){action.status='Done';action.completed=action.created+48*36e5}
      })
     })
    }
    if(!save())console.error('Unable to save the demo environment. Browser storage may be full.')
   }
}
