/* ----- Temperature corrective actions (shown only for out-of-range readings) ----- */
const TEMP_FIX_ACTIONS=['Moved product to functioning cooler','Discarded affected product','Rechecked after 15 minutes','Adjusted equipment settings','Called for equipment service','Other (describe in notes)'];
const tempFixFor=(status,module,itemId)=>status&&status.temperatureCorrections&&status.temperatureCorrections[module]&&status.temperatureCorrections[module][itemId]||null;
function tempCorrectionBox(module,item,status,getValue){
 const wrap=h('div',{class:'corr hidden','aria-live':'polite'}),
  refresh=()=>{
   const value=getValue(),flagged=!!tempFlag(item,value),record=tempFixFor(status,module,item.id);
   if(!flagged&&!record){wrap.classList.add('hidden');wrap.replaceChildren();return}
   wrap.classList.remove('hidden');
   const current=record&&String(record.tempRecorded)===String(value);
   wrap.classList.toggle('done',!!record&&(current||!flagged));
   if(record&&(current||!flagged)){
    wrap.replaceChildren(h('h4',{text:flagged?'✓ Corrective action recorded':'Corrective action on file (earlier out-of-range reading)'}),summary(record),
     flagged?h('button',{class:'btn alt',type:'button',text:'Edit Corrective Action',onclick:()=>form(record)}):null);
    return
   }
   form(record)
  },
  summary=record=>h('div',null,
   h('p',null,h('b',{text:'Product: '}),record.product),h('p',null,h('b',{text:'Temperature recorded: '}),record.tempRecorded+'°F'),
   h('p',null,h('b',{text:'Action taken: '}),record.action),
   record.followUp!==''&&record.followUp!==undefined?h('p',null,h('b',{text:'Follow-up temperature: '}),record.followUp+'°F'+(tempFlag(item,record.followUp)?' — still out of range, escalate':'')):null,
   record.notes?h('p',{class:'pre-wrap'},h('b',{text:'Notes: '}),record.notes):null,
   h('p',{class:'note',text:'Recorded by '+(record.by||'—')+' · '+acFmtTime(record.at)})),
  form=record=>{
   const value=getValue(),
    product=h('input',{type:'text',value:record&&record.product||item.text,'aria-label':'Product'}),
    recorded=h('input',{type:'text',value:value+'°F',readonly:'readonly','aria-label':'Temperature recorded'}),
    action=sel(TEMP_FIX_ACTIONS,record&&record.action||TEMP_FIX_ACTIONS[0]),
    followUp=h('input',{type:'number',step:'any',inputmode:'decimal',placeholder:'Follow-up temperature (°F)',value:record&&record.followUp!==undefined?record.followUp:'','aria-label':'Follow-up temperature'}),
    notes=h('textarea',{class:'walk-task-note','aria-label':'Corrective action notes',placeholder:'Notes…',value:record&&record.notes||''});
   action.setAttribute('aria-label','Corrective action taken');
   wrap.classList.remove('done');
   wrap.replaceChildren(h('h4',{text:'⚠ Corrective Action Required'}),
    h('div',{class:'frm'},field('Product',product),field('Temperature Recorded',recorded),field('Corrective Action Taken',action),field('Follow-Up Temperature',followUp)),
    field('Notes',notes),
    h('div',{class:'btns left'},h('button',{class:'btn',type:'button',text:'Save Corrective Action',onclick:()=>{
     const user=acUser(),fu=followUp.value.trim();
     if(!product.value.trim()){t('Enter the product.');return}
     if(action.value===TEMP_FIX_ACTIONS[TEMP_FIX_ACTIONS.length-1]&&!notes.value.trim()){t('Describe the corrective action in the notes.');return}
     if(fu!==''&&!Number.isFinite(Number(fu))){t('Enter a valid follow-up temperature.');return}
     status.temperatureCorrections=status.temperatureCorrections||{};
     const store=status.temperatureCorrections[module]||(status.temperatureCorrections[module]={}),previous=store[item.id];
     store[item.id]={product:product.value.trim(),tempRecorded:value,action:action.value,followUp:fu,notes:notes.value.trim(),by:user?user.name:'',byId:user?user.id:null,at:Date.now()};
     if(!save()){if(previous===undefined)delete store[item.id];else store[item.id]=previous;t('Unable to save the corrective action. Browser storage may be full.');return}
     t('Corrective action saved.');refresh()
    }})))
  };
 refresh();
 return {element:wrap,refresh}
}
