/* ----- Manager commentary ----- */
const CM_FIELDS=[['successes','Successes This Period'],['challenges','Challenges This Period'],['focus','Focus Areas Next Period'],['notes','Additional Notes']];
const CM_METRICS=[[/readiness|ready/,'ready','Readiness'],[/walk/,'walk','Walkthrough Completion'],[/checklist/,'check','Checklist Completion'],[/temp/,'temp','Temperature Compliance'],[/action|overdue/,'action','Action Closure Rate'],[/mvr|visit/,'mvr','MVR Score'],[/overall|score/,'score','Overall Score']];
const CM_STOP=new Set(['compliance','standards','findings','finding','improve','reduce','review','increase','process','above','below','next','period','focus','team','keep','maintain']);
const cmLines=text=>String(text||'').split(/\r?\n/).map(s=>s.replace(/^\s*[-•*]\s*/,'').trim()).filter(Boolean);
const cmTokens=text=>new Set((String(text).toLowerCase().match(/[a-z]{4,}/g)||[]).filter(w=>!CM_STOP.has(w)));
function cmBlock(label,text){
 const lines=cmLines(text);
 return h('div',{class:'cm-block'},h('h4',{text:label}),lines.length?h('ul',null,lines.map(line=>h('li',{text:line}))):h('p',{class:'note',text:'—'}))
}
function cmSnapshot(m){
 const map=new Map();
 m.findings.forEach(f=>{const key=f.category+'\u0001'+f.name;map.set(key,(map.get(key)||0)+1)});
 const rounded=v=>v==null?null:Math.round(v);
 return {score:m.score,walk:rounded(m.walk),check:rounded(m.check),temp:rounded(m.temp),action:rounded(m.action),ready:rounded(m.ready),mvr:rounded(m.mvr),
  findings:[...map.entries()].sort((a,b)=>b[1]-a[1]).slice(0,80).map(([key,count])=>({category:key.split('\u0001')[0],name:key.split('\u0001')[1],count}))}
}
function cmEvaluate(line,baseline,cur){
 const results=[],lower=line.toLowerCase(),words=cmTokens(line);
 CM_METRICS.forEach(([re,key,label])=>{
  if(re.test(lower)&&baseline[key]!=null&&cur[key]!=null){
   const now=Math.round(cur[key]),d=now-baseline[key];
   results.push(label+': '+baseline[key]+'% → '+now+'% ('+scSigned(d)+')')
  }
 });
 const curMap=new Map();
 cur.findings.forEach(f=>{const key=f.category+'\u0001'+f.name;curMap.set(key,(curMap.get(key)||0)+1)});
 const related=(category,name)=>[...cmTokens(category+' '+name)].some(w=>words.has(w)),
  before=baseline.findings.filter(f=>related(f.category,f.name)).reduce((s,f)=>s+f.count,0),
  after=[...curMap.entries()].filter(([key])=>related(...key.split('\u0001'))).reduce((s,[,n])=>s+n,0);
 if(before+after>0){
  const pct=before?Math.round((after-before)/before*100):null;
  results.push('Related findings: '+before+' → '+after+(pct==null?'':pct<0?' (Reduced '+(-pct)+'%)':pct>0?' (Increased '+pct+'%)':' (No change)'))
 }
 return results
}
const cmFor=(locationId,from,to)=>S.commentaries.find(c=>c.locationId===locationId&&c.from===from&&c.to===to)||null;
function cmSave(ctx,values,existing){
 const user=acUser(),now=Date.now(),
  visit=S.mvrVisits.filter(v=>v.status==='Complete'&&v.locationId===ctx.single.id&&v.date>=ctx.days[0]&&v.date<=ctx.days[ctx.days.length-1]).sort((a,b)=>b.date.localeCompare(a.date)||b.created-a.created)[0];
 if(existing){
  const backup=JSON.stringify(existing);
  existing.revisions=(existing.revisions||[]).concat({at:existing.updated||existing.created,byId:existing.editorId||existing.authorId,byName:existing.editorName||existing.authorName,successes:existing.successes,challenges:existing.challenges,focus:existing.focus,notes:existing.notes}).slice(-20);
  Object.assign(existing,values,{updated:now,editorId:user.id,editorName:user.name,mvrId:visit?visit.id:'',snapshot:{cur:cmSnapshot(ctx.cur),prev:cmSnapshot(ctx.prev)}});
  if(!save()){Object.assign(existing,JSON.parse(backup));return false}
  return true
 }
 const record=Object.assign({id:'cm-'+nid(),locationId:ctx.single.id,from:ctx.days[0],to:ctx.days[ctx.days.length-1],created:now,updated:now,
  authorId:user.id,authorName:user.name,authorRole:user.role,editorId:user.id,editorName:user.name,mvrId:visit?visit.id:'',
  snapshot:{cur:cmSnapshot(ctx.cur),prev:cmSnapshot(ctx.prev)},revisions:[]},values);
 S.commentaries.push(record);
 if(!save()){S.commentaries.pop();return false}
 return true
}
function cmEntry(c,open){
 const visit=c.mvrId&&S.mvrVisits.find(v=>v.id===c.mvrId);
 return h('details',open?{class:'cm-entry',open:''}:{class:'cm-entry'},
  h('summary',null,h('b',{text:acStore(c.locationId)+' · '+scDate(c.from)+' – '+scDate(c.to)}),' · '+(c.editorName||c.authorName||'—')+' · '+acFmtDate(c.updated||c.created)),
  CM_FIELDS.map(([key,label])=>cmBlock(label,c[key])),
  visit?h('p',{class:'note',text:'Linked MVR: '+mvrDate(visit.date)+' · '+visit.score+'%'}):null,
  (c.revisions||[]).length?h('p',{class:'note',text:(c.revisions.length)+' earlier revision'+(c.revisions.length===1?'':'s')+' saved.'}):null)
}
function scCtx(user){
 const f=SC_FILTER;
 if(!f.ready)return null;
 const stores=dailyLocationsForUser(user),days=scDays(f);
 if(!days||!days.length)return null;
 const scope=f.store==='all'?stores:stores.filter(s=>s.id===f.store);
 if(!scope.length)return null;
 const prevDays=scPrevDays(days);
 return {user,stores,scope,days,prevDays,cur:scMetrics(scope,days),prev:scMetrics(scope,prevDays),single:scope.length===1?scope[0]:null}
}

/* ----- Scorecard drill-down ----- */
const SC_DRILL={'Overall Performance':'overall','Walkthrough Compliance':'walk','Walkthrough Completion':'walk','Checklist Compliance':'check','Checklist Completion':'check',
 'Temperature Log Compliance':'temp','Temperature Compliance':'temp','Action Plan Resolution':'action','Actions Created':'action','Actions Closed':'action','Action Closure Rate':'action','Average Resolution Time':'action',
 'Readiness Score':'ready','Average Readiness':'ready','MVR Score':'mvr','Average MVR Score':'mvr','Current MVR':'mvr','Previous MVR':'mvr','MVR Trend':'mvr','Open Critical Actions':'critical'};
function scOpenDrill(label,key,ctx){
 const {cur,scope,days,single}=ctx,from=days[0],to=days[days.length-1],ids=new Set(scope.map(s=>s.id)),
  multi=scope.length>1,CAP=60,
  mods=prefix=>DASHBOARD_ACCESS.filter(o=>o[1].indexOf(prefix)===0),
  statusOf=(store,day)=>S.dailyStatus&&S.dailyStatus[day+'|'+store.id],
  capNote=n=>n>CAP?h('p',{class:'note',text:'Showing the first '+CAP+' of '+n+' records.'}):null,
  actionRow=a=>[scDate(a.date),multi?acStore(a.locationId):null,a.description||a.title||'Action',a.level,actionStage(a),a.ownerName||'—'].filter(x=>x!==null),
  actionHead=()=>['Date',multi?'Store':null,'Action','Priority','Stage','Owner'].filter(x=>x!==null),
  actionTable=list=>list.length?[acTable(actionHead(),list.slice(0,CAP).map(actionRow)),capNote(list.length)]:empty('No records.'),
  periodActions=S.actionItems.filter(a=>ids.has(a.locationId)&&a.date>=from&&a.date<=to),
  completionRows=prefix=>{
   const rows=[];
   scope.forEach(store=>mods(prefix).forEach(option=>{
    let done=0;days.forEach(day=>{if(dailyOptionComplete(option,statusOf(store,day)||{}))done++});
    rows.push([multi?acStore(store.id):null,option[2],done+' of '+days.length+' days',Math.round(done/days.length*100)+'%'].filter(x=>x!==null))
   }));
   return acTable([multi?'Store':null,'Form','Completed','Rate'].filter(x=>x!==null),rows)
  },
  info={
   walk:['Daily Manager Walkthroughs submitted from the dashboard.','Completed walkthroughs ÷ expected walkthroughs (each walkthrough × each day × each store in the range).',cur.walk],
   check:['Opening, Mid-Day and Closing Checklists submitted from the dashboard.','Completed checklists ÷ expected checklists (each checklist × each day × each store in the range).',cur.check],
   temp:['Temperature Logs entered from the dashboard.','In-range readings ÷ all recorded numeric readings, using each item\'s acceptable limits.',cur.temp],
   action:['Action Center items dated within the range.','Closed actions ÷ actions created in the range. Average resolution time uses created-to-completed time of closed actions.',cur.action],
   ready:['Open Action Center items on each day a store submitted any daily form.','For each submitted day: 100 minus open-action penalties (Critical 10, High 5, Medium 2, Low 1), floored at 0. The result is the average of those days. Other figures below are context, not inputs.',cur.ready],
   mvr:['Completed Management Visit Reviews dated within the range.','Average of overall scores for completed visits in the range. Trend compares the latest visit with the visit before it.',cur.mvr],
   critical:['Action Center items with Critical priority that are not closed.','Count of unresolved Critical actions dated on or before the end of the range.',null],
   overall:['The six weighted components of this scorecard.','Weighted average of available components (Walkthrough 20, Checklist 20, Temperature 15, Action Plan 15, Readiness 15, MVR 15). Components with no data are dropped and remaining weights renormalized.',cur.score]
  }[key],
  head=acTable(['Detail','Value'],[
   ['Store',single?mvrStoreLabel(single.id)+' · '+single.name:'All Locations ('+scope.length+' stores)'],['Date Range',scDate(from)+' – '+scDate(to)],
   ['Result',key==='critical'?String(cur.openCritical):key==='overall'?scPct(cur.score):scPct(info[2])],['Data Source',info[0]],['Calculation',info[1]]]);
 let records;
 if(key==='walk')records=completionRows('walk_');
 else if(key==='check')records=completionRows('check_');
 else if(key==='temp'){
  const rows=[];let total=0;
  scope.forEach(store=>days.forEach(day=>{
   const status=statusOf(store,day);
   if(!status)return;
   mods('temp_').forEach(option=>{
    if(!dailyOptionComplete(option,status))return;
    const values=status.temperatureReadings&&status.temperatureReadings[option[1]]||{};
    temperatureItemsFor(option[1]).forEach(cat=>(cat.items||[]).forEach(item=>{
     const v=values[item.id];
     if(v===undefined||v===''||!Number.isFinite(Number(v)))return;
     total++;
     if(tempFlag(item,v)){const fix=tempFixFor(status,option[1],item.id);rows.push([scDate(day),multi?acStore(store.id):null,option[2],item.text,v+'°F',fix?fix.action:'Not recorded'].filter(x=>x!==null))}
    }))
   })
  }));
  records=[h('p',{class:'note',text:total+' readings recorded · '+rows.length+' out of range.'}),rows.length?[acTable(['Date',multi?'Store':null,'Log','Item','Reading','Corrective Action'].filter(x=>x!==null),rows.slice(0,CAP)),capNote(rows.length)]:empty('No out-of-range readings.')]
 }
 else if(key==='action')records=actionTable(periodActions);
 else if(key==='critical')records=actionTable(S.actionItems.filter(a=>ids.has(a.locationId)&&a.date<=to&&a.status!=='Done'&&a.level==='critical'));
 else if(key==='mvr'){
  const visits=S.mvrVisits.filter(v=>v.status==='Complete'&&ids.has(v.locationId)&&v.date>=from&&v.date<=to).sort((a,b)=>b.date.localeCompare(a.date));
  records=visits.length?acTable(['Visit Date','Store','Reviewer','Score'],visits.map(v=>[mvrDate(v.date),acStore(v.locationId),v.reviewerRole||v.reviewer||'—',v.score+'%'])):empty('No completed management visits in this range.')
 }
 else if(key==='ready'){
  const rows=[];
  scope.forEach(store=>days.forEach(day=>{
   const status=statusOf(store,day);
   if(!status||!Object.values(status.dailySubmissions||{}).some(Boolean))return;
   const endOfDay=insightsParse(day).getTime()+864e5,
    open=S.actionItems.filter(a=>a.locationId===store.id&&a.date<=day&&!(a.status==='Done'&&a.completed&&a.completed<endOfDay)),
    penalty=open.reduce((s,a)=>s+READINESS_PENALTY[PRIORITY_LEVELS[a.level]?a.level:'medium'],0);
   rows.push([day,scDate(day),multi?acStore(store.id):null,open.length+' open',Math.max(0,100-penalty)+'%'].filter(x=>x!==null))
  }));
  rows.sort((a,b)=>b[0].localeCompare(a[0]));
  records=[h('h3',{class:'dh',text:'Related Results (context only)'}),acTable(['Measure','Result'],[['Walkthrough completion',scPct(cur.walk)],['Checklist completion',scPct(cur.check)],['Temperature compliance',scPct(cur.temp)],['Open critical actions',String(cur.openCritical)],['MVR contribution',scPct(cur.mvr)]]),
   h('h3',{class:'dh',text:'Daily Readiness'}),rows.length?[acTable(['Date',multi?'Store':null,'Open Actions','Readiness'].filter(x=>x!==null),rows.slice(0,CAP).map(r=>r.slice(1))),capNote(rows.length)]:empty('No submitted days in this range.')]
 }
 else records=acTable(['Component','Weight','Result','Contribution'],(()=>{
  const avail=SC_WEIGHTS.filter(([k])=>cur[k]!=null),w=avail.reduce((s,x)=>s+x[2],0);
  return SC_WEIGHTS.map(([k,name,weight])=>[name,weight+'%',scPct(cur[k]),cur[k]==null?'No data':(Math.round(cur[k]*weight/w*10)/10)+' pts'])
 })());
 shModal(label,[head,h('h3',{class:'dh',text:'Contributing Records'}),records])
}
function scWireDrill(report,ctx){
 const wire=(el,label)=>{
  el.classList.add('sc-click');el.tabIndex=0;el.setAttribute('role','button');el.title='View details';
  const open=()=>scOpenDrill(label,SC_DRILL[label],ctx);
  el.onclick=open;el.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}}
 };
 report.querySelectorAll('.sc-break tbody tr').forEach(tr=>{if(SC_DRILL[tr.firstChild.textContent])wire(tr,tr.firstChild.textContent)});
 report.querySelectorAll('.sc-kv').forEach(kv=>{
  const kids=[...kv.children];
  for(let i=0;i+1<kids.length;i+=2){
   const label=kids[i].textContent;
   if(SC_DRILL[label]){wire(kids[i],label);wire(kids[i+1],label)}
  }
 });
 const big=report.querySelector('.sc-big');
 if(big)wire(big,'Overall Performance')
}

/* ----- Scorecard commentary (read-only in the report, editable below it) ----- */
function scCommentarySections(report,ctx){
 const user=ctx.user,from=ctx.days[0],to=ctx.days[ctx.days.length-1],mc=$('mc');
 if(!ctx.single){
  report.append(panel('Manager Commentary',empty('Commentary is saved per store. Choose a single store to view or add commentary.')));
  return
 }
 const store=ctx.single,saved=cmFor(store.id,from,to),
  previous=S.commentaries.filter(c=>c.locationId===store.id&&c.to<from).sort((a,b)=>b.to.localeCompare(a.to))[0],
  visit=S.mvrVisits.filter(v=>v.status==='Complete'&&v.locationId===store.id&&v.date>=from&&v.date<=to&&v.commentary&&Object.keys(v.commentary).length).sort((a,b)=>b.date.localeCompare(a.date))[0];
 report.append(panel('Manager Commentary',saved?[CM_FIELDS.map(([key,label])=>cmBlock(label,saved[key])),h('p',{class:'note',text:'Saved by '+(saved.editorName||saved.authorName||'—')+' · '+acFmtDate(saved.updated||saved.created)})]:empty('No commentary has been saved for this period.'),
  visit?[h('h4',{text:'Management Visit Commentary · '+mvrDate(visit.date)}),MVR_COMMENTARY_FIELDS.filter(([key])=>visit.commentary[key]).map(([key,label])=>cmBlock(label,visit.commentary[key]))]:null));
 if(previous){
  const lines=cmLines(previous.focus);
  report.append(panel('Previous Period Focus & Results',h('p',{class:'note',text:'From commentary for '+scDate(previous.from)+' – '+scDate(previous.to)}),
   lines.length?lines.map(line=>{
    const results=cmEvaluate(line,previous.snapshot.cur,ctx.cur);
    return h('div',{class:'cm-block'},h('p',null,h('b',{text:'Previous Period Focus: '}),'“'+line+'”'),
     results.length?results.map(r=>h('p',{class:'cm-result',text:'Current Period Result: '+r})):h('p',{class:'cm-result',text:'No linked metric — review progress with the team.'}))
   }):empty('No focus areas were recorded.')))
 }
 const canEdit=hasDashboardPermission(user,'commentary'),
  history=S.commentaries.filter(c=>c.locationId===store.id).sort((a,b)=>b.to.localeCompare(a.to)||(b.updated||0)-(a.updated||0)).slice(0,20);
 if(canEdit){
  const inputs=CM_FIELDS.map(([key,label])=>h('textarea',{class:'walk-task-note','aria-label':label,placeholder:key==='notes'?'Free-text comments…':'One item per line…',value:saved?saved[key]||'':''}));
  mc.append(h('div',{class:'sc-noprint'},panel('Edit Manager Commentary',
   h('p',{class:'note',text:'Saved for '+mvrStoreLabel(store.id)+' · '+scDate(from)+' – '+scDate(to)+'. Use one line per item.'}),
   h('div',{class:'frm'},CM_FIELDS.map(([,label],i)=>field(label,inputs[i]))),
   h('div',{class:'btns left'},h('button',{class:'btn',type:'button',text:saved?'Update Commentary':'Save Commentary',onclick:()=>{
    const values={};CM_FIELDS.forEach(([key],i)=>{values[key]=inputs[i].value.trim()});
    if(!CM_FIELDS.some(([key])=>values[key])){t('Enter commentary before saving.');return}
    if(!cmSave(ctx,values,saved)){t('Unable to save commentary. Browser storage may be full.');return}
    t('Commentary saved.');drawScorecard(user)
   }})))))
 }
 if(history.length)mc.append(h('div',{class:'sc-noprint'},panel('Commentary History',history.map((c,i)=>cmEntry(c,false)))))
}
const scBaseDraw=drawScorecard;
drawScorecard=function(user){
 scBaseDraw(user);
 try{
  const report=$('mc').querySelector('.sc-report'),ctx=report&&scCtx(user);
  if(!ctx)return;
  scWireDrill(report,ctx);scCommentarySections(report,ctx)
 }catch(error){console.error('Scorecard extensions failed:',error)}
};

/* ----- Operational Insights: multi-store rollup and performance vs. commentary ----- */
function insightsRollup(user,days){
 const stores=dailyLocationsForUser(user);
 if(stores.length<2)return null;
 const rows=stores.map(store=>({store,m:scMetrics([store],days)}))
  .map(x=>{if(x.m.ready==null&&x.m.mvr==null&&x.m.action==null&&x.m.temp==null)x.m=Object.assign({},x.m,{score:null});return x})
  .sort((a,b)=>(a.m.score==null)-(b.m.score==null)||(b.m.score||0)-(a.m.score||0)||a.store.name.localeCompare(b.store.name)),
  scored=rows.filter(r=>r.m.score!=null),
  network=scored.length?Math.round(scored.reduce((s,r)=>s+r.m.score,0)/scored.length):null,
  label=r=>mvrStoreLabel(r.store.id)+' · '+r.store.name,
  card=(title,value,sub)=>h('div',{class:'ins-card'},h('b',{text:value}),h('span',{text:title}),sub?h('small',{text:sub}):null);
 return panel('Multi-Store Performance Rollup',
  h('p',{class:'note',text:'All stores you can access, for '+scDate(days[0])+' – '+scDate(days[days.length-1])+'. Scores use the Performance Scorecard formulas.'}),
  h('div',{class:'ins-grid'},card('Average Network Score',scPct(network),scored.length+' of '+rows.length+' stores scored'),
   card('Top Performer',scored.length?scPct(scored[0].m.score):'—',scored.length?label(scored[0]):null),
   card('Lowest Performer',scored.length>1?scPct(scored[scored.length-1].m.score):'—',scored.length>1?label(scored[scored.length-1]):null)),
  acTable(['Rank','Store','Overall','Readiness','MVR','Action Resolution','Walkthrough'],rows.map((r,i)=>{
   const ranked=r.m.score!=null;
   return [ranked?String(scored.indexOf(r)+1):'—',label(r),ranked?r.m.score+'%':'No data',scPct(r.m.ready),scPct(r.m.mvr),scPct(r.m.action),scPct(r.m.walk)]
  })))
}
function insightsCommentary(user,scope,days){
 const ids=new Set(scope.map(s=>s.id)),from=days[0],to=days[days.length-1],
  list=S.commentaries.filter(c=>ids.has(c.locationId)&&c.to>=from&&c.from<=to).sort((a,b)=>b.to.localeCompare(a.to)).slice(0,10),
  labels={score:'Overall Score',ready:'Readiness',walk:'Walkthrough Compliance',check:'Checklist Compliance',temp:'Temperature Compliance',action:'Action Resolution',mvr:'MVR Score'};
 return panel('Performance vs. Manager Commentary',list.length?list.map(c=>{
  const chips=Object.keys(labels).filter(k=>c.snapshot&&c.snapshot.cur[k]!=null&&c.snapshot.prev[k]!=null&&Math.abs(c.snapshot.cur[k]-c.snapshot.prev[k])>=1)
   .map(k=>{const d=c.snapshot.cur[k]-c.snapshot.prev[k];return h('span',{class:'cm-delta '+(d>0?'up':'down'),text:labels[k]+(d>0?' Improved ':' Declined ')+Math.abs(d)+'%'})});
  return h('div',{class:'cm-entry'},h('b',{text:acStore(c.locationId)+' · '+scDate(c.from)+' – '+scDate(c.to)}),
   h('div',null,chips.length?chips:h('span',{class:'note',text:'No significant metric change versus the prior period.'})),
   c.challenges?cmBlock('Associated Manager Comment — Challenges',c.challenges):null,c.successes?cmBlock('Successes',c.successes):null)
 }):empty('No manager commentary overlaps this period. Add commentary from the Performance Scorecard.'))
}
const insBaseDraw=drawInsights;
drawInsights=function(user){
 insBaseDraw(user);
 try{
  const days=insightsDays(INSIGHTS_FILTER);
  if(!days)return;
  const stores=dailyLocationsForUser(user),scope=INSIGHTS_FILTER.store==='all'?stores:stores.filter(s=>s.id===INSIGHTS_FILTER.store),
   rollup=insightsRollup(user,days);
  $('mc').append(...[rollup,hasDashboardPermission(user,'commentary')||hasDashboardPermission(user,'scorecard')?insightsCommentary(user,scope,days):null].filter(Boolean))
 }catch(error){console.error('Insights extensions failed:',error)}
};
{const user=acUser();if(user)try{renderPriorityPanel(user)}catch(error){console.error(error)}}

